query DLMNewOrganicRoute($query: String!) {
  shop { id }
  orders(first: 10, sortKey: CREATED_AT, query: $query) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id
      customerJourneySummary { ready firstVisit { landingPage } lastVisit { landingPage } }
      lineItems(first: 50) {
        pageInfo { hasNextPage endCursor }
        nodes { title currentQuantity product { id handle title } }
      }
    }
  }
}
